-- CMS Open Payments - General Payments Detail (PY2022)
-- Auto-generated by scripts/gen_evidence_pages.py: 13,250,000 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE_OF_PAYMENT") as year, count(*) as records
from THE_LIBRARY.HEALTH.FED_CMS_OPEN_PAYMENTS_2022
where "DATE_OF_PAYMENT" is not null
group by 1
order by 1
